```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology"@en ;
    rdfs:comment "An ontology formalizing securities, derivatives, debt and equity instruments, and investment funds based on financial market standards and regulatory corpus."@en .

#################################################################
#    Object Properties
#################################################################

fis:hasIssuer
    a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:label "has issuer"@en ;
    rdfs:comment "Relates a financial instrument or security to the legal entity that issued it."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isIssuerOf .

fis:isIssuerOf
    a owl:ObjectProperty ;
    rdfs:label "is issuer of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument .

fis:hasHolder
    a owl:ObjectProperty ;
    rdfs:label "has holder"@en ;
    rdfs:comment "Relates a financial instrument to the entity holding it."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isHolderOf .

fis:isHolderOf
    a owl:ObjectProperty ;
    rdfs:label "is holder of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument .

fis:hasCounterparty
    a owl:ObjectProperty ;
    rdfs:label "has counterparty"@en ;
    rdfs:comment "Relates a contract (e.g. a derivative or swap) to a participating party."@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:LegalEntity ;
    owl:inverseOf fis:isCounterpartyOf .

fis:isCounterpartyOf
    a owl:ObjectProperty ;
    rdfs:label "is counterparty of"@en ;
    rdfs:domain fis:LegalEntity ;
    rdfs:range fis:FinancialInstrument .

fis:hasUnderlying
    a owl:ObjectProperty ;
    rdfs:label "has underlying"@en ;
    rdfs:comment "Relates a derivative or structured instrument to the underlying asset, reference entity, rate, or instrument upon which its value depends."@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:isUnderlyingOf .

fis:isUnderlyingOf
    a owl:ObjectProperty ;
    rdfs:label "is underlying of"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:Derivative .

fis:hasPortfolioAsset
    a owl:ObjectProperty ;
    rdfs:label "has portfolio asset"@en ;
    rdfs:comment "Relates an investment fund to a security or financial instrument held in its portfolio."@en ;
    rdfs:domain fis:InvestmentFund ;
    rdfs:range fis:FinancialInstrument ;
    owl:inverseOf fis:isPortfolioAssetOf .

fis:isPortfolioAssetOf
    a owl:ObjectProperty ;
    rdfs:label "is portfolio asset of"@en ;
    rdfs:domain fis:FinancialInstrument ;
    rdfs:range fis:InvestmentFund .

fis:hasConversionTarget
    a owl:ObjectProperty ;
    rdfs:label "has conversion target"@en ;
    rdfs:comment "Relates a convertible security to the equity share into which it may be converted."@en ;
    rdfs:domain fis:ConvertibleSecurity ;
    rdfs:range fis:CommonStock ;
    owl:inverseOf fis:isConversionTargetOf .

fis:isConversionTargetOf
    a owl:ObjectProperty ;
    rdfs:label "is conversion target of"@en ;
    rdfs:domain fis:CommonStock ;
    rdfs:range fis:ConvertibleSecurity .

fis:hasCollateral
    a owl:ObjectProperty ;
    rdfs:label "has collateral"@en ;
    rdfs:comment "Relates a secured debt instrument to the collateral asset or asset pool backing it."@en ;
    rdfs:domain fis:SecuredDebtSecurity ;
    rdfs:range fis:FinancialAsset ;
    owl:inverseOf fis:isCollateralOf .

fis:isCollateralOf
    a owl:ObjectProperty ;
    rdfs:label "is collateral of"@en ;
    rdfs:domain fis:FinancialAsset ;
    rdfs:range fis:SecuredDebtSecurity .

#################################################################
#    Datatype Properties
#################################################################

fis:hasMaturityDate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has maturity date"@en ;
    rdfs:comment "The date on which the principal of a debt security is due to be repaid."@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:date .

fis:hasParValue
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has par value"@en ;
    rdfs:comment "The stated nominal or face amount of a security."@en ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:decimal .

fis:hasCouponRate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has coupon rate"@en ;
    rdfs:comment "The stated interest rate paid by the issuer on a debt security."@en ;
    rdfs:domain fis:DebtSecurity ;
    rdfs:range xsd:decimal .

fis:hasStrikePrice
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has strike price"@en ;
    rdfs:comment "The predetermined price at which the holder of an option can buy or sell the underlying asset."@en ;
    rdfs:domain fis:Option ;
    rdfs:range xsd:decimal .

fis:hasExpirationDate
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has expiration date"@en ;
    rdfs:comment "The last date on which a derivative contract or option may be exercised or settled."@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:date .

fis:hasIsin
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has ISIN"@en ;
    rdfs:comment "The 12-digit alphanumeric International Securities Identification Number."@en ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string .

fis:hasCreditRating
    a owl:DatatypeProperty ;
    rdfs:label "has credit rating"@en ;
    rdfs:comment "The credit assessment score assigned to a security or issuer by a rating agency."@en ;
    rdfs:domain fis:Security ;
    rdfs:range xsd:string .

fis:hasNotionalAmount
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:label "has notional amount"@en ;
    rdfs:comment "The nominal or face amount used to calculate payments on a derivative or swap."@en ;
    rdfs:domain fis:Derivative ;
    rdfs:range xsd:decimal .

#################################################################
#    Classes: Legal Entities / Parties
#################################################################

fis:LegalEntity
    a owl:Class ;
    rdfs:label "Legal Entity"@en ;
    rdfs:comment "An institution, organization, or individual capable of entering contracts, issuing securities, or holding financial assets."@en .

fis:Corporation
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Corporation"@en ;
    rdfs:comment "A commercial enterprise or joint stock company that issues stock, bonds, or commercial paper."@en .

fis:SovereignGovernment
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Sovereign Government"@en ;
    rdfs:comment "A national sovereign governing entity."@en .

fis:LocalGovernment
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Local Government"@en ;
    rdfs:comment "A state, provincial, territorial, municipal, or local authority other than a sovereign government."@en .

fis:SupranationalOrganization
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Supranational Organization"@en ;
    rdfs:comment "An international organization or development bank formed by multiple nations (e.g., World Bank, IMF)."@en .

fis:FinancialInstitution
    a owl:Class ;
    rdfs:subClassOf fis:Corporation ;
    rdfs:label "Financial Institution"@en ;
    rdfs:comment "An intermediary such as a commercial bank, investment bank, or broker-dealer."@en .

fis:CentralBank
    a owl:Class ;
    rdfs:subClassOf fis:LegalEntity ;
    rdfs:label "Central Bank"@en ;
    rdfs:comment "A public institution that manages the currency, money supply, and interest rates of a nation or monetary union."@en .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:Corporation fis:SovereignGovernment fis:LocalGovernment fis:SupranationalOrganization ) .

#################################################################
#    Classes: Top-Level Financial Concepts
#################################################################

fis:FinancialAsset
    a owl:Class ;
    rdfs:label "Financial Asset"@en ;
    rdfs:comment "A monetary asset that represents cash, an equity interest, or a contractual right to receive cash or another financial instrument."@en .

fis:FinancialInstrument
    a owl:Class ;
    rdfs:subClassOf fis:FinancialAsset ;
    rdfs:label "Financial Instrument"@en ;
    rdfs:comment "Any contract that gives rise to a financial asset of one entity and a financial liability or equity instrument of another entity."@en .

fis:Security
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LegalEntity ]
        )
    ] ;
    rdfs:label "Security"@en ;
    rdfs:comment "A tradable financial asset representing an investment claim against an issuer."@en .

#################################################################
#    Classes: Main Categories of Securities / Instruments
#################################################################

fis:DebtSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Debt Security"@en ;
    rdfs:comment "A negotiable financial instrument serving as evidence of a debt obligation, under which the issuer promises to pay interest and repay principal."@en .

fis:EquitySecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Equity Security"@en ;
    rdfs:comment "A negotiable financial instrument representing an ownership interest or residual claim in a corporation or legal entity."@en .

fis:HybridSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Hybrid Security"@en ;
    rdfs:comment "A security that combines debt-like and equity-like characteristics."@en .

fis:Derivative
    a owl:Class ;
    rdfs:subClassOf fis:FinancialInstrument ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:FinancialInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:FinancialInstrument ]
        )
    ] ;
    rdfs:label "Derivative"@en ;
    rdfs:comment "A financial contract whose value is derived from the performance of an underlying asset, index, rate, or event."@en .

fis:InvestmentFund
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Security
            [ a owl:Restriction ; owl:onProperty fis:hasPortfolioAsset ; owl:someValuesFrom fis:FinancialInstrument ]
        )
    ] ;
    rdfs:label "Investment Fund"@en ;
    rdfs:comment "A pooled investment vehicle whose shares or units represent an interest in a diversified portfolio of securities."@en .

#################################################################
#    Classes: Debt Securities and Bonds
#################################################################

fis:Bond
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Bond"@en ;
    rdfs:comment "A debt security under which the issuer contracts to pay the holder periodic interest and to repay the principal amount at maturity."@en .

fis:MoneyMarketInstrument
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    rdfs:label "Money Market Instrument"@en ;
    rdfs:comment "A short-term debt security with an original maturity of one year or less."@en .

fis:CommercialPaper
    a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Commercial Paper"@en ;
    rdfs:comment "An unsecured, short-term promissory note issued by a corporation, typically with a maturity of 270 days or less."@en .

fis:CertificateOfDeposit
    a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    rdfs:label "Certificate of Deposit"@en ;
    rdfs:comment "A time deposit promissory note issued by a bank or depository institution with a specific maturity date."@en .

fis:TreasuryBill
    a owl:Class ;
    rdfs:subClassOf fis:MoneyMarketInstrument ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:MoneyMarketInstrument
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] ;
    rdfs:label "Treasury Bill"@en ;
    rdfs:comment "A short-term sovereign debt obligation maturing in one year or less, issued at a discount."@en .

fis:CorporateBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ]
        )
    ] ;
    rdfs:label "Corporate Bond"@en ;
    rdfs:comment "A bond issued by a business corporation to raise capital."@en .

fis:GovernmentBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ]
        )
    ] ;
    rdfs:label "Government Bond"@en ;
    rdfs:comment "A medium- or long-term debt security issued by a sovereign national government."@en .

fis:MunicipalBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:LocalGovernment ]
        )
    ] ;
    rdfs:label "Municipal Bond"@en ;
    rdfs:comment "A bond issued by a state, city, municipality, or local government entity."@en .

fis:SupranationalBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ]
        )
    ] ;
    rdfs:label "Supranational Bond"@en ;
    rdfs:comment "A bond issued by an international organization such as the World Bank or IMF."@en .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:CorporateBond fis:GovernmentBond fis:MunicipalBond fis:SupranationalBond ) .

# Bond structural variations

fis:ZeroCouponBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Zero Coupon Bond"@en ;
    rdfs:comment "A bond that pays no periodic interest coupons and is issued at a deep discount, repaying face value at maturity."@en .

fis:FixedRateBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Fixed Rate Bond"@en ;
    rdfs:comment "A bond carrying a constant nominal interest rate throughout its life."@en .

fis:FloatingRateNote
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Floating Rate Note"@en ;
    rdfs:comment "A bond whose interest payment floats relative to a reference rate benchmark such as EURIBOR or SOFR."@en .

fis:PerpetualBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Perpetual Bond"@en ;
    rdfs:comment "A bond with no stated maturity date, paying interest indefinitely at borrower discretion."@en .

fis:CallableBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Callable Bond"@en ;
    rdfs:comment "A bond granting the issuer the option to redeem the debt prior to its scheduled maturity date."@en .

fis:PutableBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond ;
    rdfs:label "Putable Bond"@en ;
    rdfs:comment "A bond granting the holder the option to force early repayment from the issuer before maturity."@en .

fis:ConvertibleBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:HybridSecurity, fis:ConvertibleSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:Bond
            [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ]
        )
    ] ;
    rdfs:label "Convertible Bond"@en ;
    rdfs:comment "A bond that gives the holder the right to convert the debt into a predetermined number of shares of common stock."@en .

fis:SecuredDebtSecurity
    a owl:Class ;
    rdfs:subClassOf fis:DebtSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:DebtSecurity
            [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:FinancialAsset ]
        )
    ] ;
    rdfs:label "Secured Debt Security"@en ;
    rdfs:comment "A debt security backed by a pledge of specific collateral assets."@en .

fis:AssetBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:SecuredDebtSecurity ;
    rdfs:label "Asset-Backed Security"@en ;
    rdfs:comment "A debt security whose interest and principal payments are backed by cash flows from an underlying pool of financial assets."@en .

fis:MortgageBackedSecurity
    a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Mortgage-Backed Security"@en ;
    rdfs:comment "An asset-backed security secured by a pool of residential or commercial mortgage loans."@en .

fis:CollateralizedMortgageObligation
    a owl:Class ;
    rdfs:subClassOf fis:MortgageBackedSecurity ;
    rdfs:label "Collateralized Mortgage Obligation"@en ;
    rdfs:comment "A structured pay-through mortgage-backed security divided into tranches with differing maturities and repayment priorities."@en .

fis:CollateralizedDebtObligation
    a owl:Class ;
    rdfs:subClassOf fis:AssetBackedSecurity ;
    rdfs:label "Collateralized Debt Obligation"@en ;
    rdfs:comment "A structured asset-backed security collateralized by a pool of debt obligations such as bonds, loans, or ABS tranches."@en .

fis:CoveredBond
    a owl:Class ;
    rdfs:subClassOf fis:Bond, fis:SecuredDebtSecurity ;
    rdfs:label "Covered Bond"@en ;
    rdfs:comment "A debt security backed by cash flows from mortgages or public sector assets that remain on the issuer's balance sheet."@en .

#################################################################
#    Classes: Equity Securities and Hybrids
#################################################################

fis:Share
    a owl:Class ;
    rdfs:subClassOf fis:EquitySecurity ;
    rdfs:label "Share"@en ;
    rdfs:comment "A unit of ownership in a corporation or company (also termed stock)."@en .

fis:CommonStock
    a owl:Class ;
    rdfs:subClassOf fis:Share ;
    rdfs:label "Common Stock"@en ;
    rdfs:comment "Ordinary shares conferring voting rights and a residual claim on earnings and assets after creditors and preferred shareholders are paid."@en .

fis:PreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:Share, fis:HybridSecurity ;
    rdfs:label "Preferred Stock"@en ;
    rdfs:comment "A hybrid equity instrument that has priority over common stock in dividend payments and liquidation proceeds, typically without voting rights."@en .

fis:CumulativePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock ;
    rdfs:label "Cumulative Preferred Stock"@en ;
    rdfs:comment "Preferred stock requiring passed or unpaid dividends to accumulate in arrears before any dividends can be paid to common stockholders."@en .

fis:ConvertiblePreferredStock
    a owl:Class ;
    rdfs:subClassOf fis:PreferredStock, fis:ConvertibleSecurity ;
    owl:equivalentClass [
        a owl:Class ;
        owl:intersectionOf (
            fis:PreferredStock
            [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ]
        )
    ] ;
    rdfs:label "Convertible Preferred Stock"@en ;
    rdfs:comment "Preferred stock conferring the option to convert the preferred shares into a fixed number of common shares."@en .

fis:ConvertibleSecurity
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Convertible Security"@en ;
    rdfs:comment "A security that can be converted into equity shares of the issuer."@en .

fis:DepositaryReceipt
    a owl:Class ;
    rdfs:subClassOf fis:Security ;
    rdfs:label "Depositary Receipt"@en ;
    rdfs:comment "A negotiable instrument issued by a bank representing ownership of shares in a foreign corporation trading on a local exchange."@en .

fis:Warrant
    a owl:Class ;
    rdfs:subClassOf fis:Security, fis:Derivative ;
    rdfs:label "Warrant"@en ;
    rdfs:comment "A long-dated option issued by a corporation entitling the holder to purchase shares of stock at a specified price directly from the issuer."@en .

owl:disjointWith
    [ a owl:Axiom ;
      owl:annotatedSource fis:CommonStock ;
      owl:annotatedProperty owl:disjointWith ;
      owl:annotatedTarget fis:PreferredStock ] .

#################################################################
#    Classes: Derivatives
#################################################################

fis:Forward
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Forward"@en ;
    rdfs:comment "A customized, bilateral over-the-counter contract to buy or sell an asset at a specified price on a future date."@en .

fis:Future
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Future"@en ;
    rdfs:comment "A standardized, exchange-traded derivative contract to buy or sell an asset at a predetermined price on a specified delivery date."@en .

fis:Option
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Option"@en ;
    rdfs:comment "A financial contract conveying the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified date."@en .

fis:CallOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Call Option"@en ;
    rdfs:comment "An option granting the holder the right to purchase the underlying asset at the strike price."@en .

fis:PutOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "Put Option"@en ;
    rdfs:comment "An option granting the holder the right to sell the underlying asset at the strike price."@en .

fis:AmericanOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "American Option"@en ;
    rdfs:comment "An option contract that may be exercised at any time up to and including the expiration date."@en .

fis:EuropeanOption
    a owl:Class ;
    rdfs:subClassOf fis:Option ;
    rdfs:label "European Option"@en ;
    rdfs:comment "An option contract that can be exercised only on the expiration date itself."@en .

fis:Swap
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Swap"@en ;
    rdfs:comment "A derivative contract in which two counterparties exchange streams of cash flows calculated on a notional principal."@en .

fis:InterestRateSwap
    a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Interest Rate Swap"@en ;
    rdfs:comment "A swap agreement to exchange periodic interest rate cash flows (such as fixed for floating) in the same currency."@en .

fis:CurrencySwap
    a owl:Class ;
    rdfs:subClassOf fis:Swap ;
    rdfs:label "Currency Swap"@en ;
    rdfs:comment "A swap agreement involving the exchange of cash flows denominated in two different currencies."@en .

fis:CreditDerivative
    a owl:Class ;
    rdfs:subClassOf fis:Derivative ;
    rdfs:label "Credit Derivative"@en ;
    rdfs:comment "A contract that transfers credit risk from a protection buyer to a protection seller."@en .

fis:CreditDefaultSwap
    a owl:Class ;
    rdfs:subClassOf fis:Swap, fis:CreditDerivative ;
    rdfs:label "Credit Default Swap"@en ;
    rdfs:comment "A credit derivative swap where the seller agrees to compensate the buyer upon a default or credit event of a reference entity."@en .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:Forward fis:Future fis:Option fis:Swap ) .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:CallOption fis:PutOption ) .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:AmericanOption fis:EuropeanOption ) .

#################################################################
#    Classes: Investment Funds
#################################################################

fis:MutualFund
    a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Mutual Fund"@en ;
    rdfs:comment "An open-end investment company that pools money to purchase securities, transacting at net asset value."@en .

fis:ExchangeTradedFund
    a owl:Class ;
    rdfs:subClassOf fis:InvestmentFund ;
    rdfs:label "Exchange-Traded Fund"@en ;
    rdfs:comment "A pooled investment fund whose shares trade continuously on public stock exchanges at market prices."@en .

[] a owl:AllDisjointClasses ;
   owl:members ( fis:MutualFund fis:ExchangeTradedFund ) .
```

@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities>
    a owl:Ontology ;
    rdfs:label "Securities and Financial Instruments Ontology" ;
